import{_ as a,o as l,c as t,a4 as h}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"写作课作业-109","description":"","frontmatter":{"date":"2021-03-03T21:22:24","title":"写作课作业-109","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]},{"level":2,"title":"参考链接","slug":"参考链接","link":"#参考链接","children":[]}],"relativePath":"posts/homework/109.md","filePath":"posts/homework/109.md"}'),r={name:"posts/homework/109.md"};function i(o,e,n,p,s,c){return l(),t("div",null,[...e[0]||(e[0]=[h('<blockquote><p>《区块链小白书》之《比特币 5.区块链究竟是什么》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>区块链是有前后链起来的信息块。区块链技术，通俗的讲，无非是个不可篡改的分布式数据库技术而已。</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>不同的子账簿通过一种特定的算法（哈希算法）前后链接起来，形成总账簿。</p><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><p>先说明区块链是blockchain的“生硬翻译”，block应该理解成信息块。那blockchain，就是字面意思，信息块的链。</p><p>之后通过比特币的设计，子账簿链成总账簿，说明区块链技术是一种新的记账技术。</p><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li><p>区块（block），就是一个又一个不断生成的字账簿，这些子账簿通过特定的算法（哈希算法）前后链接起来。形成总账簿。从这个角度出发，区块链技术没什么神秘的，通俗的讲，他只不过是一种心的记账技术而已。</p></li><li><p>区块链，通俗的讲，无非是个不可篡改的分布式数据库技术而已。</p></li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>区块链在底层用和GIT类似的技术，这使得他们有些相似，比如分布式，可追溯性，不可篡改等。但因为要解决的问题不同最终长出来的东西也就完全不一样的了。</p><p>在网上流行着一个小区的大门配上了66把锁，被称为区块链链的实体化，每个人都可以开锁进入小区，被误以为是区块链的分布式管理。我想这个也是滥用类比坏处。不懂的人以为他懂了。</p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><p><a href="https://zhuanlan.zhihu.com/p/33927320" target="_blank" rel="noreferrer">Git和区块链的相似性和差异性比较</a></p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',23)])])}const _=a(r,[["render",i]]);export{u as __pageData,_ as default};
